-- support: tenant help tickets and their messages (P2-15a). See docs/modules.md (support).
--   * Ids are UUIDv7 generated by the server or the device. tenant_id leads every key and index; RLS is forced.
--   * Platform-side fields (assignee) are plain uuids: the platform team's users live outside this module, no FK.
--   * Messages are append-only. Tickets change through status and the SLA stamps only.
CREATE SCHEMA support AUTHORIZATION wb_migrator;
GRANT USAGE ON SCHEMA support TO wb_app;

CREATE TABLE support.tickets (
  tenant_id uuid NOT NULL,
  id uuid NOT NULL,
  branch_id uuid,
  subject text NOT NULL CHECK (btrim(subject) <> '' AND length(subject) <= 200),
  status text NOT NULL CHECK (status IN ('open', 'pending', 'solved', 'closed')),
  priority text NOT NULL CHECK (priority IN ('low', 'normal', 'high', 'urgent')),
  created_by uuid NOT NULL,
  assignee uuid,
  -- The plan the SLA was computed for, stored as resolved (an unknown plan is stored as 'free').
  plan_code text NOT NULL CHECK (btrim(plan_code) <> '' AND length(plan_code) <= 40),
  sla_first_response_due_at timestamptz NOT NULL,
  sla_resolution_due_at timestamptz NOT NULL,
  first_responded_at timestamptz,
  solved_at timestamptz,
  -- Sanitised by the domain before it is written (whitelisted keys, scrubbed messages). Never raw client input.
  diagnostics jsonb NOT NULL DEFAULT '{}'::jsonb CHECK (jsonb_typeof(diagnostics) = 'object'),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT tickets_pkey PRIMARY KEY (tenant_id, id),
  CONSTRAINT tickets_sla_order_chk CHECK (sla_resolution_due_at >= sla_first_response_due_at)
);
-- Keyset list filtered by status, newest first (created_at, then id as the tie-break).
CREATE INDEX tickets_status_idx ON support.tickets (tenant_id, status, created_at DESC, id DESC);
-- Keyset list over all statuses, newest first.
CREATE INDEX tickets_created_idx ON support.tickets (tenant_id, created_at DESC, id DESC);

CREATE TABLE support.ticket_messages (
  tenant_id uuid NOT NULL,
  id uuid NOT NULL,
  ticket_id uuid NOT NULL,
  author_kind text NOT NULL CHECK (author_kind IN ('tenant', 'platform')),
  author_id uuid NOT NULL,
  body text NOT NULL CHECK (btrim(body) <> '' AND length(body) <= 8000),
  -- Platform-only notes. A tenant can never write one (also enforced in the use case and the API schema).
  internal boolean NOT NULL DEFAULT false,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT ticket_messages_pkey PRIMARY KEY (tenant_id, id),
  CONSTRAINT ticket_messages_ticket_fk FOREIGN KEY (tenant_id, ticket_id)
    REFERENCES support.tickets (tenant_id, id),
  CONSTRAINT ticket_messages_internal_chk CHECK (NOT internal OR author_kind = 'platform')
);
-- A ticket's thread in order; also serves the composite foreign key.
CREATE INDEX ticket_messages_thread_idx ON support.ticket_messages (tenant_id, ticket_id, created_at);

ALTER TABLE "support"."tickets" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "support"."tickets" FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON "support"."tickets" USING ("tenant_id" = nullif(current_setting('app.tenant_id', true), '')::uuid) WITH CHECK ("tenant_id" = nullif(current_setting('app.tenant_id', true), '')::uuid);
ALTER TABLE "support"."ticket_messages" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "support"."ticket_messages" FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON "support"."ticket_messages" USING ("tenant_id" = nullif(current_setting('app.tenant_id', true), '')::uuid) WITH CHECK ("tenant_id" = nullif(current_setting('app.tenant_id', true), '')::uuid);

-- Least privilege: default privileges give wb_app SELECT, INSERT, UPDATE, DELETE on every new table, so revoke the
-- rest here. Only the ticket columns the use cases change are updatable; messages are append-only.
REVOKE UPDATE, DELETE, TRUNCATE ON ALL TABLES IN SCHEMA support FROM wb_app;
GRANT UPDATE (status, first_responded_at, solved_at, updated_at) ON support.tickets TO wb_app;
